def task(key,material_de,material_en,prompt_de,prompt_en,solution_de,solution_en,essential):
 return dict(caseKey=key,status='new_synthetic_author_material_not_learner_work',materialDe=material_de,materialEn=material_en,promptDe=prompt_de,promptEn=prompt_en,solutionDe=solution_de,solutionEn=solution_en,positiveEssentialConditions=essential,claimLimit='Fictional controlled school model; no executed experiment, clinical inference, mastery or independent approval.')
def component(key,title,title_en,description,description_en,scopes,tasks,goal=None,prereqs=None):
 return dict(candidateKey=key,canonicalGoalId=goal,newAssignedGoalId=None,status='author_component_candidate_needs_independent_scope_and_P_review',title=title,titleEn=title_en,description=description,descriptionEn=description_en,sourceScopes=scopes,existingGoalBinding='supplementary bounded material; existing full goal and old P payloads unchanged' if goal else 'null-ID candidate; no canonical insertion, registry entry or runnable projection',proposedPrerequisiteGoalCandidates=prereqs or [],prerequisiteResolution='Semantic and actual current prerequisite inventory supplied; final goal/component IDs, placement and effective runtime route require separate review. No NI recombination obligation inferred.',tasks=tasks,wholeSourceClosure=False)
components=[]
components.append(component('mutation_levels_gen_chromosome_genome','Gen-, Chromosomen- und Genommutationen am Modell unterscheiden','Distinguish gene, chromosome and genome mutations in models','Die lernende Person kann an vorgegebenen DNA- und Chromosomenmodellen Veränderungen innerhalb eines Gens, der Struktur eines Chromosomenabschnitts und der Chromosomenzahl unterscheiden und ihre Zuordnung zum Gen-, Chromosomen- oder Genomniveau begründen.','The learner can use supplied DNA and chromosome models to distinguish changes within a gene, in chromosome-segment structure and in chromosome number, and justify their classification as gene, chromosome or genome mutations.',['SN Klasse10: kennen Ursachen/Typen; Gen/Chromosom/Genom','TH9/10: genetische Variabilität mit Gen/Chromosom/Genom, Ursachen/Folgen erläutern'],[
 task('levels-a','Fiktiver Organismus: 2n=4, zwei Chromosomenpaare A/B. Fall1: in Gen G wird ACGT zu ATGT, Anzahl und große Chromosomenstruktur bleiben gleich. Fall2: ein Abschnitt von A mit zwölf Genen liegt doppelt auf A, Anzahl bleibt4. Fall3: fünf statt vier Chromosomen, ein zusätzliches B.','Fictional organism: 2n=4, chromosome pairs A/B. Case1: gene G changes ACGT to ATGT; chromosome number and large-scale structure are unchanged. Case2: a segment of A containing twelve genes is duplicated on A; total remains4. Case3: five chromosomes, including an extra B.','Ordne alle drei Fälle begründet dem Mutationsniveau zu. Welche Messung unterscheidet Fall2 von Fall3? Was ist über ein Merkmal noch offen?','Classify all three cases by mutation level with reasons. Which measurement separates cases2 and3? What remains unknown about traits?','1 Genmutation: lokale Sequenzänderung. 2 Chromosomenmutation: großer Abschnitt ist verdoppelt, die Zahl bleibt4. 3 Genommutation: Zahl5. Anzahl und Abschnittsstruktur sind getrennte Größen. Ohne Genprodukt-/Merkmalsdaten folgt kein bestimmter Merkmals- oder Krankheitsbefund.','1 Gene mutation: local sequence change.2 Chromosome mutation: a large segment is duplicated while number stays4.3 Genome mutation: number5. Number and segment structure are different measurements. Without gene-product/trait data, no particular trait or disease follows.',['Explain scale from actual model changes','Separate segment duplication from added whole chromosome','Limit trait/function conclusions']),
 task('levels-b','Neues fiktives Modell: 2n=6 (A1/A2,B1/B2,C1/C2). L: Verlust einer Base in einem kurzen Gen, sonst unverändert. M: Umkehrung eines Abschnitts mit acht Genen auf C1, Zahl6. N: C2 fehlt, Zahl5.','New fictional model: 2n=6 (A1/A2,B1/B2,C1/C2).L: loss of one base in a short gene, otherwise unchanged.M: inversion of a segment containing eight genes on C1, number6.N: C2 is missing, number5.','Erkläre die Zuordnung von L/M/N. Warum reicht das Wort Verlust ohne den Maßstab nicht zur Zuordnung?','Explain the classification of L/M/N. Why is the word loss insufficient without scale?','L Genmutation, M strukturelle Chromosomenmutation, N Genommutation. Der Verlust einer Base und eines ganzen Chromosoms betrifft unterschiedliche Ebenen. Die Art der Sequenzänderung allein legt ohne Maßstab keine Chromosomen-/Genomkategorie fest.','L is a gene mutation,M a structural chromosome mutation,N a genome mutation. Loss of one base and of a whole chromosome affect different levels. A change label alone does not determine chromosome/genome category without scale.',['Correctly classify fresh cases','Use base/segment/number distinction rather than label matching','Do not equate all loss events'])],prereqs=[DNA]))
components.append(component('point_and_genome_mutation','Punkt- und Genommutationen am Modell einordnen','Classify point and genome mutations in models','Die lernende Person kann in vorgegebenen Fällen eine Änderung an einer einzelnen Basenpaarposition von einer Änderung der Chromosomenzahl unterscheiden und als Punkt- beziehungsweise Genommutation einordnen.','The learner can distinguish a change at a single base-pair position from a change in chromosome number in supplied cases and classify them as point or genome mutations.',['ST Schuljahrgang10/Einführungsphase: ausdrücklich Genom- und Punktmutation'],[
 task('point-genome-a','Schulmodell: Referenz-Gen ACTA; Variante ATTA, sonst alle genetischen Informationen unverändert. Referenz-Chromosomensatz A1,A2,B1,B2; zweite Variante A1,A2,B1,B2,B3. Punktmutation bedeutet in diesem Material eine Änderung an genau einer Basenpaarposition; gezeigt werden Substitutionen.','School model: reference gene ACTA; variant ATTA, all other genetic information unchanged. Reference complement A1,A2,B1,B2; second variant A1,A2,B1,B2,B3. In this material, a point mutation affects exactly one base-pair position; examples are substitutions.','Vergleiche die Veränderungen und begründe Punkt-/Genomzuordnung. Kann eine unveränderte Chromosomenzahl eine Punktmutation ausschließen?','Compare changes and justify point/genome classification. Can an unchanged chromosome count rule out a point mutation?','ACTA→ATTA verändert eine Position C→T: Punktmutation im festgelegten Modell. B3 erhöht die Chromosomenzahl4→5: Genommutation. Unveränderte Anzahl schließt eine lokale Sequenzänderung nicht aus. Es wird keine universelle Punktmutationsdefinition über alle Fachkonventionen behauptet.','ACTA→ATTA changes one position,C→T: a point mutation under the model definition.B3 raises number4→5: a genome mutation. Unchanged number does not rule out local sequence change. The working definition is not asserted as universal across terminology conventions.',['Locate single altered position','Count whole chromosomes independently','Explain evidence limit of chromosome counting']),
 task('point-genome-b','Neuer fiktiver Ausgangssatz2n=6. P: in einem Gen GCAA→GCTA, Zahl6. Q: homologes Chromosom C2 fehlt, Zahl5. DNA-Sequenzen einzelner Gene wurden bei Q nicht gemessen.','New fictional baseline2n=6.P: gene GCAA→GCTA, number6.Q: homologous chromosome C2 is absent, number5. Individual gene sequences were not measured in Q.','Erkläre beide Kategorien. Welche zusätzliche Untersuchung wäre nötig, um eine weitere Punktmutation bei Q zu prüfen?','Explain both categories. What extra investigation would be needed to check for an additional point mutation in Q?','P: eine Basenposition A→T, Punktmutation. Q: Zahländerung, Genommutation. Sequenzvergleich eines definierten Genabschnitts wäre nötig, um dort eine zusätzliche Punktmutation festzustellen; die Zahl5 zeigt sie nicht.','P changes one base position,A→T: point mutation.Q changes chromosome number: genome mutation. Sequence comparison of a defined gene region would be needed to establish an additional point mutation there; count5 does not establish it.',['Use fresh sequence/count data','Separate simultaneous possible change levels','Name a matching sequence test without diagnosis'])],prereqs=[DNA]))
components.append(component('mutagen_causes_and_protection','Mutagene Einflüsse und begründeten Schutz erklären','Explain mutagenic influences and justified protection','Die lernende Person kann anhand eines kontrollierten Modells erklären, wie mutagene Einflüsse die Häufigkeit bleibender Veränderungen der Erbinformation erhöhen können, und aus vorgegebenen Expositionsdaten begründete Möglichkeiten zur Verringerung des Einflusses ableiten.','The learner can use a controlled model to explain how mutagenic influences can increase the frequency of persistent changes to genetic information and derive justified ways of reducing the influence from supplied exposure data.',['BY12 GA/EA: Ursachen und Schutzsensibilisierung ausdrücklich','MV10: Mutagene und Gefahrenpotenzial im Alltag reflektieren','SN10: Mutagenursachen kennen','ST10: Mutagene und genetische Umweltrisiken bewerten','TH9/10: Mutationsursachen erläutern; Schutz ist didaktische Ergänzung ohne zusätzliche amtliche Schutzklausel'],[
 task('mutagen-protection-a','Fiktive physikalische Einwirkung R erzeugt im Modell DNA-Schäden; nicht behobene Veränderungen können bei weiterer Kopie dauerhaft werden. Drei sonst gleiche Gruppen mit je1000 Zelllinien: ohne R3 bestätigte neue Sequenzänderungen; mit R27; R hinter einer für R getesteten Abschirmung6. Gleiche Zeit, gleiche Kopienzahl, gleiche Prüfmethode.','Fictional physical influence R damages DNA in this model; unresolved changes may become persistent on later copying. Otherwise identical groups,1000 cell lineages each: no R3 confirmed new sequence changes;R27;R behind a barrier tested for R6. Same time,copy number and assay.','Erkläre den Ursachenweg und vergleiche die Häufigkeiten. Begründe den Schutz durch Abschirmung im Modell und seine Grenze. Bedeutet3 ohne R, dass Mutation nur durch R entstehen kann?','Explain the causal path and compare frequencies. Justify barrier protection in this model and its limit. Do3 cases without R mean mutation can arise only from R?','R→DNA-Schaden→mögliche bleibende Sequenzänderung bei nicht erfolgreicher Korrektur. Beobachtet0,3%,2,7%,0,6%; R-Gruppe neunfach gegenüber Kontrolle. Abschirmung reduziert hier Einwirkung/Änderungshäufigkeit, beseitigt sie nicht. Die Kontrollfälle zeigen Hintergrundveränderungen; ein Mutagen ist keine notwendige Ursache jeder Mutation. Keine Übertragung dieser Zahlen auf Personen.','R→DNA damage→possible persistent sequence change if correction fails. Observed rates0.3%,2.7%,0.6%;R is ninefold control. The barrier reduces influence/change frequency here without eliminating it. Control cases show background changes;a mutagen is not necessary for every mutation. These rates do not transfer to people.',['Connected cause explanation','Correct controlled comparison and nonzero baseline','A justified protective action and no absolute-protection claim']),
 task('mutagen-protection-b','Fiktiver chemischer Stoff M reagiert im Modell mit DNA. Gleiches Material in1000 Zelllinien je Gruppe: geschlossene Ersatzanlage ohne M-Kontakt2 neue Änderungen; offene M-Anwendung18; offene Anwendung mit ungeprüfter Papierabdeckung17. Materialkarte: Papier hält M nicht zurück, geschlossene Ersatzanlage verhindert den Kontakt unter den angegebenen Bedingungen.','Fictional chemical M reacts with DNA in this model.1000 lineages per group: closed substitute system without M contact2 new changes;open M use18;open use with untested paper cover17. Material card: paper does not retain M;the closed substitute system prevents contact under stated conditions.','Werte die Daten aus und wähle eine begründete Schutzoption. Warum genügt ein sichtbarer Gegenstand als Schutzbeleg nicht? Begrenze die Aussage über einzelne Zellen.','Interpret data and choose a justified protective option. Why is a visible covering alone insufficient evidence of protection? Limit claims about individual cells.','Die Kontaktgruppen zeigen1,8%/1,7%, die kontaktvermeidende Gruppe0,2%. Im Material ist die geschlossene Ersatzanlage begründet; Papier hat keine belegte Schutzwirkung gegen M. Gruppendaten bedeuten nicht, dass jede exponierte Zelle mutiert oder die Kontrolle frei von allen Veränderungen ist.','Contact groups show1.8%/1.7%,the contact-avoiding group0.2%.The closed substitute system is justified by the material;paper has no established protection against M. Group data do not mean every exposed cell mutates or control has no changes.',['Match measure to influence and evidence','Use fresh controlled rates','Avoid deterministic cell/health conclusion'])]))
components.append(component('somatic_and_germline','Folgen somatischer und Keimbahnmutationen im Zelllinienmodell unterscheiden','Distinguish somatic and germline mutation consequences in lineage models','Die lernende Person kann an einem vorgegebenen Zelllinienmodell erklären, wie Zeitpunkt und betroffene Zelllinie die Ausbreitung einer Mutation im Organismus und ihre mögliche Weitergabe durch Keimzellen beeinflussen.','The learner can use a supplied lineage model to explain how timing and affected lineage influence a mutation’s spread within an organism and possible transmission through gametes.',['MV10: Auswirkungen auf Körperzellen und Keimbahn','BY12 GA/EA: somatische Mutation und Keimbahnmutation'],[
 task('lineage-a','Fiktives Tier: Körperzelllinie K und keimzellbildende Linie G sind bereits getrennt. Dieselbe DNA-Änderung tritt entweder in K oder in G auf. Alle Tochterzellen einer betroffenen Zelle erhalten im Modell die Änderung; zwischen K und G gibt es keinen Zellwechsel. Nur aus G entstehen Keimzellen für geschlechtliche Fortpflanzung.','Fictional animal: somatic lineage K and gamete-forming lineage G are already separate. The same DNA change occurs in either K or G. All daughter cells inherit it in this model;cells do not move between K/G.Only G produces gametes for sexual reproduction.','Verfolge beide Änderungen. Welche kann über eine beteiligte Keimzelle in Nachkommen gelangen? Warum ist auch die somatische Änderung eine Mutation?','Trace both changes. Which can enter offspring through a participating gamete? Why is the somatic change still a mutation?','K: Änderung bleibt in ihrer Körperzell-Abstammungslinie und wird in diesem Tiermodell nicht über Keimzellen weitergegeben. G: betroffene Keimzellen können sie weitergeben, wenn sie tatsächlich zur Befruchtung beitragen. Beide verändern Erbinformation; Vererbung an Nachkommen ist kein Definitionskriterium jeder Mutation.','K change stays in its somatic descendants and is not transmitted via gametes in this animal model.G can transmit it if an affected gamete actually participates in fertilisation.Both alter genetic information;offspring inheritance is not a defining condition for every mutation.',['Follow actual lineage separation','State conditional germline transmission','Distinguish cellular inheritance from offspring inheritance']),
 task('lineage-b','Neues fiktives Tiermodell: Mutation E entsteht in der Zygote vor Trennung der Zelllinien und bleibt in beiden Linien. Mutation S entsteht spät in einer Körperzelle. Mutation G entsteht in einer einzelnen fertigen Keimzelle; genau diese Keimzelle wird im angegebenen Fall nicht für die Befruchtung verwendet.','New fictional animal model: E arises in the zygote before lineages separate and persists in both.S arises late in a somatic cell.G arises in one mature gamete;that exact gamete is not used for fertilisation in the given case.','Vergleiche Ausbreitung und mögliche Weitergabe von E/S/G. Kann aus dem Wort Keimbahnmutation allein abgeleitet werden, dass der gegebene Nachkomme die Änderung trägt?','Compare spread and potential transmission of E/S/G. Does the word germline mutation alone establish that the given offspring carries it?','E erreicht hier beide Linien und kann über betroffene Keimzellen weitergegeben werden. S betrifft nur späte somatische Nachkommen. G ist keimbahnbezogen, wird aber in dieser Befruchtung nicht übertragen. Betroffene Linie, Zeitpunkt und verwendete Keimzelle sind entscheidend; daraus folgt keine bestimmte Erkrankung.','E reaches both lineages here and can pass through affected gametes.S affects only late somatic descendants.G is germline-related but is not transmitted in this fertilisation.Lineage,timing and participating gamete matter;no particular disease follows.',['Transfer to early versus late timing','Use fertilisation information','Do not treat germline change as guaranteed transmission'])],prereqs=['1d2b1038-dcd5-529a-b085-9e14f1d58c76']))
components.append(component('mutation_vs_modification','Mutation und Modifikation mit Kontrolldaten unterscheiden','Distinguish mutation and modification using controlled data','Die lernende Person kann an vorgegebenen Vergleichsdaten begründen, ob ein Merkmalsunterschied auf einer Änderung genetischer Information oder auf einer Umweltwirkung bei unveränderter genetischer Information beruht, und die Grenzen eines Merkmalsbefunds benennen.','The learner can use supplied comparison data to justify whether a trait difference results from altered genetic information or an environmental influence without such alteration,and state the limits of trait observations.',['MV10: Mutation/Modifikation vergleichen','SN10: Vielfalt/Information auf Mutation und Modifikation anwenden','ST10: kriteriengeleitet vergleichen und folgern','TH9/10: genetische und umweltbedingte Variabilität erläutern'],[
 task('mutation-modification-a','Fiktive Pflanzenklone besitzen zunächst dieselbe Erbinformation. Im Modell bleibt sie während der Lichtänderung unverändert; der untersuchte Abschnitt bestätigt dies. Gruppe L: wenig Licht, Blätter12 Einheiten; Gruppe H: viel Licht, Blätter20; Abschnitt bleibt bei beiden unverändert. Neue Stecklinge im gleichen Licht zeigen beide16. Variante M besitzt eine bestätigte bleibende DNA-Änderung; ihre Blätter messen16 und unterscheiden sich äußerlich hier nicht.','Fictional plant clones initially have identical genetic information. The model stipulates that this information remains unchanged during the light shift; the assayed region confirms this.L under low light has leaves12 units;H under high light20;the region remains unchanged.New cuttings under equal light both reach16.Variant M has a confirmed persistent DNA change and leaves16,without a visible difference here.','Begründe den Modifikationsfall und den Mutationsfall. Warum beweist ein gleiches Aussehen keine unveränderte DNA?','Justify modification and mutation classifications. Why does similar appearance not prove unchanged DNA?','L/H: im Modell umweltbedingte Merkmalsänderung ohne genetische Änderung, unter gleichen Bedingungen rückgeführt: Modifikation. M: gemessene DNA-Änderung, Mutation trotz gleichem Blattwert. Aussehen allein trennt die Ursachen nicht; der Befund betrifft den definierten Abschnitt und die angegebenen Bedingungen.','L/H are environmental trait changes without genetic alteration in the model,and equal conditions remove the difference:modification.M is a measured DNA change,a mutation despite equal leaf value.Appearance alone does not distinguish causes;the result is bounded to the defined region and conditions.',['Use genotype and environment controls','Explain mutation can lack visible effect','Bound conclusions to measured material']),
 task('mutation-modification-b','Fiktive Varianten A/B: in gemeinsamer Umgebung Blattlänge8/10; DNA am untersuchten Gen unterscheidet sich an einer Position. Höhere Temperatur verändert die Blattwerte vorübergehend auf14/16, ohne weitere Sequenzänderung. Nach Rückkehr sinken sie auf8/10. Die DNA-Unterschiede wurden vor und nach dem Temperaturwechsel bestätigt.','Fictional variants A/B: common environment leaf lengths8/10;the assayed gene differs at one position.Higher temperature temporarily shifts lengths to14/16 without further sequence changes.Return restores8/10.The DNA differences were confirmed before/after the temperature change.','Trenne die bestätigte genetische Variante von der zusätzlichen Umweltwirkung. Welche kausale Aussage über den Unterschied8/10 bleibt offen?','Separate the confirmed genetic variant from the additional environmental effect. What causal claim about the8/10 difference remains open?','Die bestätigte genetische Variante besteht unter beiden Temperaturen. Die zusätzliche6-Einheiten-Änderung hängt im Modell von der Temperatur ab und ist eine Modifikation. Merkmale können mehrere Beiträge besitzen. Eine einzelne Sequenzänderung beweist ohne weitere Funktionsdaten nicht, dass sie allein jeden Unterschied verursacht.','The confirmed genetic variant persists at both temperatures.The additional6-unit shift depends on temperature in the model and is a modification.Traits can have multiple contributions.A sequence difference alone does not prove it solely causes every difference without further functional data.',['Separate persistent genotype from reversible environmental shift','Recognise coexistence','Avoid claiming all between-line differences are caused by one measured variant'])]))
components.append(component('protein_function_from_mutation_data','Mutationsfolgen für eine gemessene Proteinfunktion begründen','Justify mutation effects on a measured protein function','Die lernende Person kann in einem vorgegebenen Genkontext eine Mutation mit der Änderung des codierten Proteins verknüpfen und mithilfe kontrollierter Funktionsdaten begründen, welche Wirkung im untersuchten Modell belegt ist.','The learner can connect a mutation to a change in the encoded protein within a supplied gene context and use controlled functional data to justify the effect supported in the studied model.',['BY12 GA/EA: Wirkung auf Funktion des codierten Proteins erläutern'],[
 task('protein-function-a','Fiktives intronfreies Gen, codierender DNA-Strang5′→3′, Start und Leseraster vorgegeben: Referenz ATG GAA TTC TAA; Variante V ATG GAC TTC TAA; Variante W ATG GAG TTC TAA. Materialcode: AUG=Met,GAA/GAG=Glu,GAC=Asp,UUC=Phe,UAA=Stopp. Gleiche gereinigte Proteinmenge, gleiche Bedingungen: Aktivität Referenz100±4,V12±2,W98±4 Einheiten.','Fictional intron-free gene,coding strand5′→3′,fixed start/frame: reference ATG GAA TTC TAA;V ATG GAC TTC TAA;W ATG GAG TTC TAA.Code:AUG=Met,GAA/GAG=Glu,GAC=Asp,UUC=Phe,UAA=stop.Equal purified protein amounts and conditions:activity reference100±4,V12±2,W98±4 units.','Leite mRNA/Produktfolgen ab und verbinde sie mit den gemessenen Aktivitäten. Welche Wirkung ist für V belegt und was darf aus W nicht allgemein geschlossen werden?','Derive mRNA/product sequences and connect them to activity measurements.What effect is supported for V,and what universal claim cannot be drawn from W?','Referenz AUG GAA UUC UAA→Met–Glu–Phe; V AUG GAC UUC UAA→Met–Asp–Phe; W AUG GAG UUC UAA→Met–Glu–Phe. V zeigt bei kontrollierter Menge im Test stark reduzierte Aktivität. W ist synonym und hier nicht klar abweichend; das beweist nicht, dass jede synonyme Mutation in jedem Genkontext funktionsneutral ist. Keine klinische Diagnose.','Reference AUG GAA UUC UAA→Met–Glu–Phe;V AUG GAC UUC UAA→Met–Asp–Phe;W AUG GAG UUC UAA→Met–Glu–Phe.V has strongly reduced tested activity at controlled quantity.W is synonymous and shows no clear difference here;this does not prove every synonymous mutation neutral in every gene context.No clinical diagnosis.',['Correct codon/product link','Use measured function rather than sequence alone','Account for equal amounts and measurement spread']),
 task('protein-function-b','Neues fiktives Bindungsprotein: intronfreier markierter Abschnitt des codierenden DNA-Strangs, 5′→3′. Referenz GAA GGT (=Glu–Gly). Variante P GAC GGT (=Asp–Gly), Variante D verliert das ganze GGT-Codon. Rest und Leseraster sind gleich, alle Proteine liegen im Test mit1µM vor. Ligandenbindung: Referenz40±3,P75±3,D39±3 Einheiten. Materialcode ist vorgegeben; keine Daten zu anderen Proteinaufgaben.','New fictional binding protein:intron-free marked segment of the coding DNA strand, 5′→3′. Reference GAA GGT (=Glu–Gly).P has GAC GGT (=Asp–Gly);D loses the entire GGT codon.Rest/frame unchanged;all proteins tested at1µM.Ligand binding:reference40±3,P75±3,D39±3 units.Supplied code;no other function data.','Erkläre die beiden Gen-/Proteinänderungen und den Funktionsbefund. Warum folgt weder jede Mutation ist Funktionsverlust noch D ist in allen Funktionen unverändert?','Explain both gene/protein changes and functional findings.Why do neither every mutation loses function nor D is unchanged in all functions follow?','P: Basensubstitution, Glu→Asp, im Test höhere Bindung. D: Deletion eines ganzen Codons, Verlust von Gly ohne Leserasterverschiebung im gegebenen Abschnitt; Bindung im Streubereich der Referenz. Funktionswirkungen hängen vom Kontext und der gemessenen Funktion ab; höhere Bindung ist keine Aussage über Gesundheit oder sämtliche Aufgaben.','P is a base substitution,Glu→Asp,and increased tested binding.D deletes one whole codon,losing Gly without shifting the given frame;binding lies within reference spread.Functional effects depend on context and tested function;higher binding says nothing about health or all protein roles.',['Mechanism for both alterations','Explain in-frame deletion','Use fresh gain/no-clear-change functional data'])],goal=FF,prereqs=['475eebb4-4eb0-524f-b1ec-4a672bf856d2']))
components.append(component('replication_error_control_and_repair','Bedeutung von Fehlerkontrolle und DNA-Reparatur erklären','Explain the significance of error control and DNA repair','Die lernende Person kann an einem einfachen Kopiermodell erklären, wie Fehlerkontrolle und Reparatur zur Erhaltung genetischer Information beitragen, und begründen, weshalb nicht jede fehlerhafte Paarung zu einer bleibenden Mutation wird und Reparatur keinen vollkommenen Schutz garantiert.','The learner can use a simple copying model to explain how error control and repair help preserve genetic information,and justify why not every mispairing becomes a persistent mutation and repair does not guarantee perfect protection.',['TH9/10: Bedeutung von Fehlerkontrolle und Reparatur','BY12 GA/EA2.4 Inhalte: Bedeutung von Reparaturenzymen; EA PCR-Vergleich bleibt eigene Pflicht'],[
 task('repair-a','Fiktives Kopiermodell: alter Matrizenstrang3′–T A C G–5′, neuer Strang5′–A T A C–3′. Regel A–T/C–G; der neue Strang ist markiert. Kontroll-/Reparaturmodell vergleicht Paarungen, entfernt den falschen neuen Baustein und ergänzt ihn anhand des intakten alten Strangs. Bei10000 Kopierpositionen werden30 Fehlpaarungen gefunden,24 davon korrigiert.','Fictional copying model:old template3′–T A C G–5′,new5′–A T A C–3′.Rule A–T/C–G;new strand marked.Control/repair checks pairings,removes the wrong new base and replaces it using the intact old strand.Among10000 copied positions,30 mispairs are found and24 corrected.','Lokalisiere und korrigiere die Fehlpaarung. Erkläre Kontrolle, Reparatur und Informationskonstanz. Was bedeutet die verbleibende Zahl6, und weshalb sind30 Fehlpaarungen nicht automatisch30 dauerhafte Mutationen?','Locate and correct the mispair.Explain checking,repair and information stability.What does the remaining6 mean,and why are30 mispairs not automatically30 persistent mutations?','Position3: C–A statt C–G; neuer Strang wird5′–A T G C–3′. Kontrolle findet den Unterschied, Reparatur stellt im Modell die vorgesehene Paarung anhand der intakten Vorlage her.30−24=6 zunächst nicht korrigierte Fehlpaarungen; erst der weitere Verlauf zeigt bleibende Veränderungen. Erfolgreiche Korrektur verhindert deren Fixierung, aber nicht jeder Fehler wird behoben.','Position3 is C–A rather than C–G;new strand becomes5′–A T G C–3′.Checking detects the mismatch;repair restores pairing using the intact template.30−24=6 initially unresolved mispairs;later events determine persistence.Successful correction prevents fixation,but not every error is repaired.',['Correct orientation/site/base','Connect checking and template-based restoration','Separate mismatch from fixed mutation and no error-free claim']),
 task('repair-b','Neues fiktives Modell: alte Vorlage3′–G T A C–5′, neue Kopie5′–C A G G–3′. Intakte Vorlage und neue Kopie sind markiert. Modell R korrigiert anhand der Vorlage, Modell N erkennt den Fehler, korrigiert aber nicht. Nach erneuter Verdopplung entstehen aus der unkorrigierten Kopie im Modell auch dauerhaft geänderte Tochter-Duplexe.','New fictional model:old template3′–G T A C–5′,new copy5′–C A G G–3′.Intact template/new copy marked.R repairs using the template;N detects but does not repair.After another copying round,the unrepaired copy can produce daughter duplexes with persistent altered sequence in this model.','Bestimme richtige Kopie und Fehlerposition. Vergleiche R/N mechanistisch. Warum ist Erkennen ohne Korrigieren keine ausreichende Informationssicherung, und warum darf daraus kein universeller Reparaturwirkungsgrad folgen?','Determine correct copy and error site.Compare R/N mechanistically.Why is detection without correction insufficient information protection,and why does this establish no universal repair efficiency?','Richtige Kopie5′–C A T G–3′; Position3 ist G statt T gegenüber A. R entfernt den falschen neuen Baustein und setzt T ein. Bei N bleibt die Kopie verändert und kann die Änderung an Tochter-Duplexe weitergeben. Erkennen allein stellt die Sequenz nicht wieder her. Das Einzelfallmodell liefert weder eine reale Fehlerhäufigkeit noch einen universellen Reparaturwirkungsgrad.','Correct copy5′–C A T G–3′;position3 has G instead of T opposite A.R removes the wrong new base and inserts T.N retains the altered copy,which can pass changes to daughter duplexes.Detection alone does not restore sequence.This single model establishes neither real error frequency nor universal repair efficiency.',['Solve fresh complementary sequence','Explain different downstream copying consequences','Respect intact-template/model boundary'])],prereqs=[REP]))
