def effective(k,visiting=None):
 visiting=set() if visiting is None else visiting
 if k in visiting:return set()
 visiting=visiting|{k};s=set(goals[k].get('requires',[]))
 for pk in parents.get(k,[]):s|=effective(pk,visiting)
 return s-{k}
def closure(k):
 seen=set();todo=list(effective(k))
 while todo:
  x=todo.pop()
  if x in seen:continue
  assert x in goals,x
  seen.add(x);todo.extend(effective(x))
 return sorted(seen)
